import { ClipboardList, Sparkles } from "lucide-react";

import { cn } from "@/lib/utils";

/**
 * Honest, always-visible label for whether a study pack was actually
 * generated by AI from the student's file, or came from the built-in demo
 * question bank (AI not configured, disabled, or the call failed). Never let
 * demo content masquerade as AI-generated — that's the one thing this
 * component exists to prevent.
 */
export function SourceBadge({ source, className }: { source: "ai" | "demo"; className?: string }) {
  const isAi = source === "ai";
  return (
    <span
      title={
        isAi
          ? "Generated by AI from the text we read in your file"
          : "AI generation isn't configured or wasn't available — these are demo questions, not generated from your file"
      }
      className={cn(
        "flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-bold",
        isAi
          ? "border-emerald-300/40 bg-emerald-400/15 text-emerald-100"
          : "border-white/20 bg-white/10 text-white/70",
        className,
      )}
    >
      {isAi ? <Sparkles className="size-3" /> : <ClipboardList className="size-3" />}
      {isAi ? "AI-generated" : "Demo question bank"}
    </span>
  );
}
